with unpacked as (select id, plan, effective_from, currency, discounts, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price from price_tiers where effective_from between '2023-06-26' and '2024-08-01') select date_trunc('month', effective_from) as activity_month, sort_array(collect_set(plan)) as plan_list, count(distinct currency) as distinct_currencies from unpacked group by date_trunc('month', effective_from) order by distinct_currencies;
